package com.lianxibu.site.service.jobs;
import static org.junit.jupiter.api.Assertions.*;
import com.lianxibu.site.domain.protocol.*;
import com.lianxibu.site.repository.jobs.*;
import com.lianxibu.site.service.content.ReportInputProfile;
import com.lianxibu.site.service.jobs.GenerationFlowService.*;
import java.time.*;
import java.time.temporal.TemporalAdjusters;
import java.util.*;
import org.junit.jupiter.api.Test;
/** Actual formal complete no-input daily preparation and postcommit proof. Source/model/settings genesis is fictional. */
class ReportPeriodNoUpdateTest {
 boolean mysql(){return false;}
 ReportNoUpdateProofTest h;ReportPeriodInputComponentService period;LocalDate last;Instant cutoff;
 void setup()throws Exception{h=new ReportNoUpdateProofTest(){@Override boolean mysql(){return ReportPeriodNoUpdateTest.this.mysql();}};h.setup();var base=h.f.f.f.data.nativeData().fixture().f();last=h.f.f.scope.day().with(TemporalAdjusters.nextOrSame(DayOfWeek.SUNDAY));cutoff=last.plusDays(1).atTime(5,0).atZone(ZoneId.of("Asia/Shanghai")).toInstant();period=new ReportPeriodInputComponentService(base.source,new ReportOriginalCompletionService(base.source,base.tx),v->{throw new AssertionError("no body eligibility may be requested for program no update");},h.service,base.tx);}
 ReportPeriodInputComponentService.Captured capture(){return period.capture(Stage.WEEKLY_REPORT,last,cutoff);}
 @Test void TrueNativeNoUpdateCoversOnlyItsDateWithoutBodyCitationOrAiDependency()throws Exception{setup();var available=h.service.observe(h.f.f.scope);assertFalse(available.availableAt().isAfter(cutoff));var c=capture();assertEquals(List.of(h.f.f.scope.day()),c.sourceProof().noUpdateDates());assertEquals(6,c.missing().size());assertTrue(c.candidates().isEmpty());assertTrue(c.dependencies().isEmpty());assertTrue(c.referenceTargets().isEmpty());assertSame(c,h.f.f.f.rr(()->period.verifyObserved(c)));assertTrue(c.originalByteSize()>available.originalByteSize());var command=new Prepare("report:weekly:"+last,1,Stage.WEEKLY_REPORT,last,null,List.of(),List.of(),List.of(),false,"a".repeat(64));var frozen=new ReportInputSnapshotService((cmd,t)->c.sourceProof()).freeze(command,cutoff);assertEquals("coverage_only",frozen.state());assertEquals(h.f.f.scope.day().toString(),CanonicalJson.parse(frozen.snapshotJson()).get(ReportInputProfile.FIELD).get("coverage").get("no_update_dates").get(0).asText());assertEquals(2,h.f.f.f.data.nativeData().fixture().f().sends);}
 @Test void UnobservedOrLateNativeNoInputIsRetainedButCannotCoverAtThePeriodCutoff()throws Exception{setup();assertTrue(capture().sourceProof().noUpdateDates().isEmpty());assertEquals(7,capture().missing().size());h.clock=Clock.fixed(cutoff.plusNanos(1000),ZoneOffset.UTC);h.compose();var available=h.service.observe(h.f.f.scope);var base=h.f.f.f.data.nativeData().fixture().f();period=new ReportPeriodInputComponentService(base.source,new ReportOriginalCompletionService(base.source,base.tx),v->{throw new AssertionError();},h.service,base.tx);var c=capture();assertTrue(c.sourceProof().noUpdateDates().isEmpty());assertEquals(7,c.missing().size());assertTrue(c.originalByteSize()>available.originalByteSize());assertSame(c,h.f.f.f.rr(()->period.verifyObserved(c)));}
 @Test void OriginalFirstDamageOrRemovalInvalidatesWholeCapturedPeriodAndCannotBorrowCurrentBody()throws Exception{setup();h.service.observe(h.f.f.scope);var old=capture();var base=h.f.f.f.data.nativeData().fixture().f();base.jdbc.update("DELETE FROM jobs WHERE target_type='report_no_update_first'");assertThrows(RuntimeException.class,()->h.f.f.f.rr(()->period.verifyObserved(old)));assertTrue(capture().sourceProof().noUpdateDates().isEmpty());h.service.observe(h.f.f.scope);base.jdbc.update("UPDATE jobs SET operator_id='fictional-wrong-program' WHERE target_type='report_no_update_first'");assertThrows(RuntimeException.class,this::capture);}
 @Test void ActualMonthKeepsEveryUnknownDateAndCompleteOriginalBudgetIsMandatory()throws Exception{setup();var available=h.service.observe(h.f.f.scope);var day=h.f.f.scope.day();var month=day.withDayOfMonth(day.lengthOfMonth());var at=month.plusDays(1).atTime(5,0).atZone(ZoneId.of("Asia/Shanghai")).toInstant();var c=period.capture(Stage.MONTHLY_REPORT,month,at);assertEquals(List.of(day),c.sourceProof().noUpdateDates());assertEquals(day.lengthOfMonth()-1,c.missing().size());var base=h.f.f.f.data.nativeData().fixture().f();var small=new ReportPeriodInputComponentService(base.source,new ReportOriginalCompletionService(base.source,base.tx),v->{throw new AssertionError();},h.service,base.tx,8192);assertThrows(GenerationFlowService.CapacityGuarded.class,()->small.capture(Stage.MONTHLY_REPORT,month,at));assertTrue(c.originalByteSize()>available.originalByteSize());assertThrows(RuntimeException.class,()->period.verifyObserved(c));}
}
